entries[25470] = { ["name"] = "Golden Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Golden Gryphon mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half. -Gryphon Master Talonaxe\"\nVendor:\nTannec Stonebeak\nZone:\nStormwind City\nCost:" }
